INSERT INTO ledlenser.brand_catalog (sku, label, gtin, upc, category_path, division, family, sheet_status, model, edition, color, short_description, description, key_features, map_price, max_lumens, min_lumens, ip_rating, weight_g, rechargeable, battery_type, included_accessories, youtube_url, datasheet_url, user_manual_url, keywords, source_file) VALUES
  ('503220', 'Ledlenser H5R Headlamp', '847706104270', '847706104270', 'Headlamps > H Series', 'Headlamps', 'H Series', 'Complete', 'H5R', 'Standard', 'Black', 'Tasks around the house, in the garden or for occasional DIY projects and painting job: The H5R is the ideal headlamp for everyday use.', 'Tasks around the house and the occasional crafting or painting job: The H5R is the ideal headlamp for everyday use. Whether you are preparing the garden shed for winter, squeezing in a last-minute painting job or checking a fuse box—reliable light makes all the difference. Not only does it allow you to finish your task no matter the time of day; it also reveals the beauty of the little things: A drowsy hedgehog in a dark corner of your garden or the sparkle of a long-lost bracelet underneath your couch. The Advanced Focus System delivers the ideal light for any range and task—simply use the focus ring for stepless focusing and the encoder for dimming. In spot mode, the beam range of your H5R is up to 275 m. The powerful battery also operates while charging, so you never run out of light—and is located at the back of your head for a balanced weight distribution. And: Our lights are made for a brighter future—therefore, your H5R contains recycled materials13.', 'Stepless dimming and focusing (Advanced Focus System) | Long-range vision: Beam range of up to 275 m (spot) | Powerful battery: Charges via USB-C and operates while charging | Sustainable: Use of recycled materials13 and 7-year warranty* | Element-proof: High water and dust resistance (IP67)', 104.95, 750, 10, 'IP67', 187, true, '18650 Li-Ion Rechargeable Battery (3.6V, 10.8Wh)', 'Charging cable (USB-C), 1 set of rechargeable batteries (18650 Li-Ion)', 'https://www.youtube.com/watch?v=oMqfvWUQ_OU', 'https://drive.google.com/file/d/1p4SBx7rzOR5CWDAYp6UJe1M1ZxM_rhX3/view?usp=drivesdk', 'https://swfilesystem.ledlenser.com/prod/public/media/68/34/89/1750928744/Warnings_25Languages_V5-50x38cm-20240507.pdf?ts=1768789724', 'headlamp,rechargeable head lamp,head torch,rechargeable headtorch', 'Ledlenser Product Data Import File V1.0 11-2.xlsx'),
  ('503351', 'Ledlenser H5R Pro Headlamp', '847706104287', '847706104287', 'Headlamps > H Series', 'Headlamps', 'H Series', 'Complete', 'H5R Pro', 'Pro Edition', 'Black', 'If you need a robust, reliable headlamp for work, the H5R Pro is the right choice: ideal for painters, electricians and installers.', 'If you need a robust, no-nonsense headlamp for work, the H5R Pro is the right choice: It provides reliable illumination and reveals the details that matter—an unevenly painted corner, a forgotten screw when you are about to finish your maintenance job or even an outdated yet quirky electrical installation. The Advanced Focus System offers the ideal light for any range and task—simply use the focus ring for stepless focusing and the encoder for dimming. In spot mode, the beam range of your H5R Pro is up to 275 m. The powerful battery also operates while charging, so you never run out of light on your shift—and is located at the back of your head for a balanced weight distribution. You can easily attach the H5R Pro to your helmet using one of the included mounting options. There is no need to worry if things get rough; rubber bumpers protect the lamp head, while the rubberized control elements can be used with gloves. When not in use, you can safely store and transport your headlamp in the enclosed pouch. And: Our lights are made for a brighter future—therefore, your H5R Pro contains recycled materials13.', 'Stepless dimming and focusing (Advanced Focus System) and beam range of up to 275 m (spot) | Powerful battery: Charges via USB-C and operates while charging | Attaches to helmet via included helmet mount, Ledlenser Connect adapter, adhesive pads, helmet fixing clips and rubberized headband | Robust: Element-proof (IP67), rubber bumpers to protect the lamp head and rubberized control elements for glove-friendly use | Sustainable: Use of recycled materials13 and 7-year warranty*', 114.95, 750, 10, 'IP67', 192, true, '18650 Li-Ion Rechargeable Battery (3.6V, 10.8Wh)', 'Charging cable (USB-C), 1 set of rechargeable batteries (18650 Li-Ion), Pouch H-series 2026, Helmet connecting kit, Fixing clips', 'https://www.youtube.com/watch?v=PhXVDfX1jdg', 'https://drive.google.com/file/d/1khCeaeoHb2glr44EfFXDsGivdOwJhAtk/view?usp=drivesdk', 'https://swfilesystem.ledlenser.com/prod/public/media/68/34/89/1750928744/Warnings_25Languages_V5-50x38cm-20240507.pdf?ts=1768789724', 'headlamp,rechargeable head lamp,helmet headlamp,professional headtorch,work headlamp,work head torch', 'Ledlenser Product Data Import File V1.0 11-2.xlsx'),
  ('503221', 'Ledlenser H7R Headlamp', '847706104294', '847706104294', 'Headlamps > H Series', 'Headlamps', 'H Series', 'Complete', 'H7R', 'Standard', 'Black', 'Built to accompany you in everyday life, on tasks around the house and garden, DIY projects or painting jobs: The H7R headlamp.', 'Whether you are working around the house, planning your next DIY project or on the job as a painter or electrician: You like to keep busy and rarely let the dark stop you. With the H7R headlamp, you have the power to reveal small miracles and big surprises: From a mouse scurrying through the leaves in your flowerbeds to years-old memories scribbled on the wall underneath the wallpaper. The Advanced Focus System offers the ideal light for any range and task, so you do not miss such joyous moments—simply use the focus ring for stepless focusing and the encoder for dimming. In spot mode, the beam range of your H7R is up to 350 m. The powerful battery also operates while charging, so you never run out of light—and is located at the back of your head for a balanced weight distribution. And: Our lights are made for a brighter future—therefore, your H7R contains recycled materials13.', 'Stepless dimming and focusing (Advanced Focus System) | Long-range vision: Beam range of up to 350 m (spot) | Powerful battery: Charges via USB-C and operates while charging | Sustainable: Use of recycled materials13 and 7-year warranty* | Element-proof: High water and dust resistance (IP67)', 129.95, 1200, 15, 'IP67', 252, true, '21700 Li-Ion Rechargeable Battery (3.6V, 4600mAh, 16.56Wh)', 'Charging cable (USB-C), 1 set of rechargeable batteries (21700 Li-Ion)', 'https://www.youtube.com/watch?v=JEmas9Cbcf0', 'https://drive.google.com/file/d/1tAkXNgHv2ENNyIvmymQB6nOW5xUqMp09/view?usp=drivesdk', 'https://swfilesystem.ledlenser.com/prod/public/media/68/34/89/1750928744/Warnings_25Languages_V5-50x38cm-20240507.pdf?ts=1768789724', 'headlamp,rechargeable head lamp,head torch,rechargeable headtorch', 'Ledlenser Product Data Import File V1.0 11-2.xlsx'),
  ('503352', 'Ledlenser H7R Pro Headlamp', '847706104300', '847706104300', 'Headlamps > H Series', 'Headlamps', 'H Series', 'Complete', 'H7R Pro', 'Pro Edition', 'Black', 'You do not shy away from hard work—if you have the right equipment. With the H7R Pro headlamp, you are ready for the next professional challenge.', 'You do not shy away from hard work—if you have the right equipment. If you work as an electrician, plumber or in maintenance, the H7R Pro belongs in your toolbox. The robust headlamp illuminates dark corners and reveals even the tiniest issue while you are working on your customer’s plumbing, upgrading outdated wiring or maintaining a boiler. To make sure your light matches the task at hand, you can rely on the Advanced Focus System—simply use the focus ring for stepless focusing and the encoder for dimming. In spot mode, the beam range of your H7R Pro is up to 350 m. Its powerful battery also operates while charging, so you never run out of light on your shift—and is located at the back of your head for a balanced weight distribution. You can easily attach the H7R Pro to your helmet using one of the included mounting options. There is no need to worry if things get rough; rubber bumpers protect the lamp head, while the rubberized control elements can be used with gloves. When not in use, you can safely store and transport your headlamp in the enclosed pouch. And: Our lights are made for a brighter future—therefore, your H7R Pro contains recycled materials13.', 'Stepless dimming and focusing (Advanced Focus System) and beam range of up to 350 m (spot) | Powerful battery: Charges via USB-C and operates while charging | Attaches to helmet via included helmet mount, Ledlenser Connect adapter, adhesive pads, helmet fixing clips and rubberized headband | Robust: Element-proof (IP67), rubber bumpers to protect the lamp head and rubberized control elements for glove-friendly use | Sustainable: Use of recycled materials13 and 7-year warranty*', 149.95, 1200, 15, 'IP67', 260, true, '21700 Li-Ion Rechargeable Battery (3.6V, 4600mAh, 16.56Wh)', 'Charging cable (USB-C), 1 set of rechargeable batteries (21700 Li-Ion), Pouch H-series 2026, LL-Connect baseplate - 3M Tape, Fixing clips', 'https://www.youtube.com/watch?v=MSwxzbVqqlk', 'https://drive.google.com/file/d/1HL6p4O9OHyNt7cDh4qqa4pJ7EWfTmaXg/view?usp=drivesdk', 'https://swfilesystem.ledlenser.com/prod/public/media/68/34/89/1750928744/Warnings_25Languages_V5-50x38cm-20240507.pdf?ts=1768789724', 'headlamp,rechargeable head lamp,helmet headlamp,professional headtorch,work headlamp,work head torch', 'Ledlenser Product Data Import File V1.0 11-2.xlsx'),
  ('503222', 'Ledlenser H15R Headlamp', '847706104317', '847706104317', 'Headlamps > H Series', 'Headlamps', 'H Series', 'Complete', 'H15R', 'Standard', 'Black', 'For challenging outdoor adventures, whether hiking, boating or water sports: the H15R headlamp is built to perform after dark.', 'For challenging outdoor adventures, whether hiking, boating or water sports: the H15R headlamp is built to perform after dark. It reliably guides your way after dark and reveals what you might otherwise have missed—a rare flower along your path as you climb a mountain or a heron near the lakeshore while you are out on the boat. The Advanced Focus System offers the ideal light for any range and task—simply use the focus ring for stepless focusing and the encoder for dimming. In spot mode, the beam range of your H15R is up to 450 m. The powerful battery also operates while charging, so you never run out of light—and is located at the back of your head for a balanced weight distribution. And: Our lights are made for a brighter future—therefore, your H15R contains recycled materials13.', 'Stepless dimming and focusing (Advanced Focus System) | Long-range vision: Beam range of up to 450 m (spot) | Powerful battery: Charges via USB-C and operates while charging | Sustainable: Use of recycled materials13 and 7-year warranty* | Element-proof: High water and dust resistance (IP67)', 204.95, 3000, 15, 'IP67', 387, true, '2x 21700 Li-Ion Rechargeable Battery Pack (7.4V, 4800mAh, 35.52Wh)', 'Charging cable (USB-C), 1 set of rechargeable batteries (2x 21700 Li-Ion)', 'https://www.youtube.com/watch?v=762n_yBXmBo', 'https://drive.google.com/file/d/1RDXaiM0Tti3myNXLjjgorTVoCwgD01D1/view?usp=drivesdk', 'https://swfilesystem.ledlenser.com/prod/public/media/68/34/89/1750928744/Warnings_25Languages_V5-50x38cm-20240507.pdf?ts=1768789724', 'headlamp,rechargeable head lamp,head torch,rechargeable headtorch', 'Ledlenser Product Data Import File V1.0 11-2.xlsx'),
  ('503354', 'Ledlenser H15R Pro Headlamp', '847706104324', '847706104324', 'Headlamps > H Series', 'Headlamps', 'H Series', 'Complete', 'H15R Pro', 'Pro Edition', 'Black', 'A lamp as hard-working and reliable as you are—be it in masonry, track maintenance or tunnel construction. The H15R Pro is up to the challenge.', 'A headlamp as hard-working and reliable as you are—be it in masonry, track maintenance or tunnel construction. The H15R Pro is up to the challenge. It illuminates both vast tunnel systems and railway tracks up close, revealing crucial details along the way so you can safely and efficiently do your job. The Advanced Focus System offers the perfect light for any range and task—simply use the focus ring for stepless focusing and the encoder for dimming. In spot mode, the beam range of your H15R Pro is up to 450 m. Its powerful battery also operates while charging, so you never run out of light on your shift—and is located at the back of your head for a balanced weight distribution. You can easily attach the H15R Pro to your helmet using one of the included mounting options. There is no need to worry if things get rough; rubber bumpers protect the lamp head, while the rubberized control elements can be used with gloves. When not in use, you can safely store and transport your headlamp in the enclosed pouch. And: Our lights are made for a brighter future—therefore, your H15R Pro contains recycled materials13.', 'Stepless dimming and focusing (Advanced Focus System) and beam range of up to 450 m (spot) | Powerful battery: Charges via USB-C and operates while charging | Attaches to helmet via included helmet mount, Ledlenser Connect adapter, adhesive pads, helmet fixing clips and rubberized headband | Robust: Element-proof (IP67), rubber bumpers to protect the lamp head and rubberized control elements for glove-friendly use | Sustainable: Use of recycled materials13 and 7-year warranty*', 229.95, 3000, 15, 'IP67', 403, true, '2x 21700 Li-Ion Rechargeable Battery Pack (7.4V, 4800mAh, 35.52Wh)', 'Charging cable (USB-C), 1 set of rechargeable batteries (2x 21700 Li-Ion), Pouch H-series 2026, Helmet connecting kit, Fixing clips', 'https://www.youtube.com/watch?v=AtopQsQ8NHM', 'https://drive.google.com/file/d/1b7lGNufkqI6A4GXiTJ5eBRpGsWUYR6xQ/view?usp=drivesdk', 'https://swfilesystem.ledlenser.com/prod/public/media/68/34/89/1750928744/Warnings_25Languages_V5-50x38cm-20240507.pdf?ts=1768789724', 'headlamp,rechargeable head lamp,helmet headlamp,professional headtorch,work headlamp,work head torch', 'Ledlenser Product Data Import File V1.0 11-2.xlsx'),
  ('503355', 'Ledlenser H9R Headlamp', '847706104331', '847706104331', 'Headlamps > H Series', 'Headlamps', 'H Series', 'Complete', 'H9R', 'Standard', 'Black', 'Powerful yet relatively compact: The H9R headlamp accompanies you on rescue missions and outdoor challenges in the mountains or on the water.', 'Powerful yet relatively compact: The H9R accompanies you on rescue missions and outdoor challenges in the mountains or on the water. The headlamp is equipped with technological innovations allowing you to venture out in the dark and reveal critical details: locating an injured person in need of medical care, a treacherous spot on a mountain trail—or a rare bird in the dark woods. To make sure you always have the best possible lighting, you can rely on the innovative Adaptive Light Beam for automatic dimming and focusing and thus hands-free use of your H9R. If you prefer manual control, the enhanced Digital Advanced Focus System is the way to go. By turning the digital focus ring, you can digitally switch from flood to spot to suit any range or task. You can also choose between red light to help you preserve your night vision, green light for wildlife observation and blue light to make liquids visible—while the optional red rear light offers additional visibility. Its powerful battery also operates while charging, so you never run out of light—and is located at the back of your head for a balanced weight distribution. And: Our lights are made for a brighter future—therefore, your H9R contains recycled materials13.', 'Automatic dimming and focusing (Adaptive Light Beam) for hands-free use as well as red, green and blue front light and optional red rear light | Intuitive focusing (Digital Advanced Focus System) via digital focus ring | Powerful battery: Charges via USB-C and operates while charging | Sustainable: Use of recycled materials13 and 7-year warranty* | Element-proof: High water and dust resistance (IP67)', 174.95, 2400, 20, 'IP67', 290, true, '21700 Li-Ion Rechargeable Battery (3.6V, 4600mAh, 16.56Wh)', 'Charging cable (USB-C), 1 set of rechargeable batteries (21700 Li-Ion)', 'https://www.youtube.com/watch?v=i61-V0UMKfo', 'https://drive.google.com/file/d/1nab1eVc1Djei9Fxu5zTXNAolzAYe6ioY/view?usp=drivesdk', 'https://swfilesystem.ledlenser.com/prod/public/media/68/34/89/1750928744/Warnings_25Languages_V5-50x38cm-20240507.pdf?ts=1768789724', 'headlamp,rechargeable head lamp,head torch,rechargeable headtorch,RGB headlamp,autofocus head torch,digital head lamp', 'Ledlenser Product Data Import File V1.0 11-2.xlsx'),
  ('503224', 'Ledlenser H9R Pro Headlamp', '847706104348', '847706104348', 'Headlamps > H Series', 'Headlamps', 'H Series', 'Complete', 'H9R Pro', 'Pro Edition', 'Black', 'Powerful, surprisingly compact and up to any professional challenge: The H9R Pro headlamp weathers harsh conditions on big and small construction sites alike.', 'Powerful, surprisingly compact and up to any professional challenge: The H9R Pro weathers harsh conditions on big and small construction sites alike. It is packed with technological innovations enabling you to work in the dark without compromise—and reveals crucial details so you can work efficiently and safely; a bolt you almost forgot to tighten before closing the engine room again, a blown fuse or a leak in the coolant reservoir of a client’s car. To make sure you always have the best possible lighting at work, you can rely on the innovative Adaptive Light Beam for automatic dimming and focusing and thus hands-free use of your H9R Pro. If you prefer manual control, the enhanced Digital Advanced Focus System is the way to go. By turning the digital focus ring, you can digitally switch from flood to spot to suit any range or task. You can also choose between red light to help you preserve your night vision, green light for wildlife observation and blue light to make liquids visible—while the optional red rear light offers additional visibility. Its powerful battery also operates while charging, so you never run out of light on your shift—and is located at the back of your head for a balanced weight distribution. You can easily attach the H9R Pro to your helmet using one of the included mounting options, while the rubberized control elements can be used with gloves. When not in use, you can safely store and transport your headlamp in the enclosed pouch. And: Our lights are made for a brighter future—therefore, your H9R Pro contains recycled materials13.', 'Automatic dimming and focusing (Adaptive Light Beam) for hands-free use as well as red, green and blue front light and optional red rear light | Intuitive focusing (Digital Advanced Focus System) via digital focus ring | Attaches to helmet via included helmet mount, Ledlenser Connect adapter, adhesive pads, helmet fixing clips and rubberized headband | Powerful battery: Charges via USB-C and operates while charging | Robust: Element-proof (IP67) and rubberized control elements for glove-friendly use', 189.95, 2400, 20, 'IP67', 286, true, '21700 Li-Ion Rechargeable Battery (3.6V, 4600mAh, 16.56Wh)', 'Charging cable (USB-C), 1 set of rechargeable batteries (21700 Li-Ion), Pouch H-series 2026, LL-Connect baseplate - 3M Tape, Fixing clips', 'https://www.youtube.com/watch?v=a_G74Vzn_7U', 'https://drive.google.com/file/d/1RPKDdNiQ9t2T9llaem2-2nhm_uEYBWPB/view?usp=drivesdk', 'https://swfilesystem.ledlenser.com/prod/public/media/68/34/89/1750928744/Warnings_25Languages_V5-50x38cm-20240507.pdf?ts=1768789724', 'headlamp,rechargeable head lamp,RGB headlamp,autofocus head torch,digital head lamp,helmet headlamp,professional headtorch,work headlamp,work head torch', 'Ledlenser Product Data Import File V1.0 11-2.xlsx'),
  ('503356', 'Ledlenser H19R Headlamp', '847706104355', '847706104355', 'Headlamps > H Series', 'Headlamps', 'H Series', 'Complete', 'H19R', 'Standard', 'Black', 'The H19R headlamp makes after-dark adventures brighter, easier, and more exciting than ever: From slopes to open water, it gives you the power to push further and experience more.', 'The H19R headlamp makes after-dark adventures brighter, easier, and more exciting: From slopes to open water, it gives you the power to push further and experience more. It reveals moguls or ice patches when skiing or snowboarding after dark, shines your way when hunting at dusk or helps you dock your sailboat at the pier after a long day on the water. To make sure you always have the best possible light, you can rely on the innovative Adaptive Light Beam for automatic dimming and focusing and thus hands-free use of your H19R. If you prefer manual control, the enhanced Digital Advanced Focus System is the way to go. By turning the digital focus ring, you can digitally switch from flood to spot to suit any range or task. You can also choose between red light to help you preserve your night vision, green light for wildlife observation and blue light to make liquids visible—while the optional red rear light offers additional visibility. The powerful battery also operates while charging, so you never run out of light on your adventures—and is located at the back of your head for a balanced weight distribution. You can use the Ledlenser Connect App for remote control and personalization. And: Our lights are made for a brighter future—therefore, your H19R contains recycled materials13.', 'Extreme performance with up to 3800 lm (boost), red, green and blue front light as well as optional red rear light | Automatic (Adaptive Light Beam) and manual dimming and focusing (Digital Advanced Focus Function) | Remote control and personalization via Ledlenser Connect App | Extremely powerful battery: Charges via USB-C and operates while charging | Element-proof: High water and dust resistance (IP67)', 279.95, 3800, 20, 'IP67', 387, true, '2x 21700 Li-Ion Rechargeable Battery Pack (7.38V, 4800mAh, 35.42Wh)', 'Charging cable (USB-C), 1 set of rechargeable batteries (2x 21700 Li-Ion)', 'https://www.youtube.com/watch?v=axFIuDCpKSU', 'https://drive.google.com/file/d/1ylBaDDcnlE_dWRbbMUdr9EDKf8yqcRqA/view?usp=drivesdk', 'https://swfilesystem.ledlenser.com/prod/public/media/68/34/89/1750928744/Warnings_25Languages_V5-50x38cm-20240507.pdf?ts=1768789724', 'headlamp,rechargeable head lamp,head torch,rechargeable headtorch,RGB headlamp,autofocus head torch,digital head lamp,Bluetooth headlamp,head torch with app control,high-end headlamp', 'Ledlenser Product Data Import File V1.0 11-2.xlsx'),
  ('503226', 'Ledlenser H19R Pro Headlamp', '847706104362', '847706104362', 'Headlamps > H Series', 'Headlamps', 'H Series', 'Complete', 'H19R Pro', 'Pro Edition', 'Black', 'Built for the most demanding work environments underground and low-light conditions: The H19R Pro headlamp delivers powerful illumination at work.', 'Built for the most demanding work environments underground and low-light conditions: The H19R Pro delivers powerful illumination at work, whether in tunnel construction, railway maintenance or carpentry. The headlamp effortlessly illuminates vast areas and reveals critical details such as damage to a railroad switch or an aesthetic flaw in woodworking. To make sure you always have the best possible light, you can rely on the innovative Adaptive Light Beam for automatic dimming and focusing and thus hands-free use of your H19R Pro. If you prefer manual control, the enhanced Digital Advanced Focus System is the way to go. By turning the digital focus ring, you can digitally switch from flood to spot to suit any range or task. You can also choose between red light to help you preserve your night vision, green light for wildlife observation and blue light to make liquids visible—while the optional red rear light offers additional visibility. The powerful battery also operates while charging, so you never run out of light on your shift—and is located at the back of your head for a balanced weight distribution. You can easily attach the H19R Pro to your helmet using one of the included mounting options, while the rubberized control elements can be used with gloves. The Ledlenser Connect App offers remote control and personalization options. When not in use, you can safely store and transport your headlamp in the enclosed pouch. And: Our lights are made for a brighter future—therefore, your H19R Pro contains recycled materials13.', 'Extreme performance with up to 3800 lm (boost), red, green and blue front light as well as optional red rear light | Automatic (Adaptive Light Beam) and manual dimming and focusing (Digital Advanced Focus Function) | Remote control and personalization via Ledlenser Connect App | Extremely powerful battery: Charges via USB-C and operates while charging | Robust: Element-proof (IP67) and rubberized control elements for glove-friendly use', 299.95, 3800, 20, 'IP67', 390, true, '2x 21700 Li-Ion Rechargeable Battery Pack (7.38V, 4800mAh, 35.42Wh)', 'Charging cable (USB-C), 1 set of rechargeable batteries (2x 21700 Li-Ion), Pouch H-series 2026, Helmet connecting kit, Fixing clips', 'https://www.youtube.com/watch?v=WMyGDCadiM8', 'https://drive.google.com/file/d/1GaubDqmsERB7Yh45h8rm2_qjABlvx2eb/view?usp=drivesdk', 'https://swfilesystem.ledlenser.com/prod/public/media/68/34/89/1750928744/Warnings_25Languages_V5-50x38cm-20240507.pdf?ts=1768789724', 'headlamp,rechargeable head lamp,RGB headlamp,autofocus head torch,digital head lamp,helmet headlamp,professional headtorch,work headlamp,work head torch,Bluetooth headlamp,head torch with app control,high-end headlamp', 'Ledlenser Product Data Import File V1.0 11-2.xlsx'),
  ('503229', 'Ledlenser H21R Headlamp (Metallic Grey)', '847706104379', '847706104379', 'Headlamps > H Series', 'Headlamps', 'H Series', 'Complete', 'H21R', 'Standard', 'Metallic Grey', 'Brilliant performance under extreme conditions: The H21R headlamp is built for extreme sports on land and water, as well as demanding work environments underground and at night.', 'Brilliant performance under extreme conditions: The H21R is designed for extreme sports on land and water, as well as demanding work environments underground and at night. The powerful headlamp provides reliable illumination—and reveals obstacles when riding downhill on a mountain bike in the dark, guides your way on the boat in poor visibility or effortlessly illuminates vast tunnels and railway tracks. In spot mode, it can be used as a powerful signal on the water or in the air, while its homogeneous flood light allows you to discover the smallest details up close, such as a barnacle on the anchor of your boat or a minor technical malfunction affecting the engine of a train. To make sure you always have the best possible light, you can rely on the innovative Adaptive Light Beam for automatic dimming and focusing and thus hands-free use of your H21R. If you prefer manual control, the enhanced Digital Advanced Focus System is the way to go. Use the buttons to digitally switch from flood to spot to suit any range or task. You can also choose between red light to help you preserve your night vision, green light for wildlife observation and blue light to make liquids visible—while the optional red rear light and reflective headband offer additional visibility. The powerful battery also operates while charging, so you never run out of light on your adventures or a long shift—and is located at the back of your head for a balanced weight distribution. You can also easily mount the H21R on your helmet via the included mounting accessories and use the Ledlenser Connect App for remote control and personalization. When not in use, you can safely store and transport your headlamp in the exclusive hard-shell case. And: Our lights are made for a brighter future—therefore, your H21R contains recycled materials13.', 'Ultimate performance with up to 10,000 lm (boost), red, green and blue front light as well as optional red rear light | Automatic (Adaptive Light Beam) and manual dimming and focusing (Digital Advanced Focus Function) | Extremely powerful battery: Charges via USB-C and operates while charging | Remote control and personalization via Ledlenser Connect App | Exclusive hard-shell case for safe transport and storage', 469.95, 10000, 40, 'IP67', 530, true, '4x 18650 Li-Ion Rechargeable Battery Pack', 'Charging cable (USB-C), 1 set of rechargeable batteries (4x 18650 Li-Ion), Hard Case', 'https://www.youtube.com/watch?v=nNjr94QbFEM', 'https://drive.google.com/file/d/1W-4u1IZTOocvSNnuyIOoeSRAj5o7VyRB/view?usp=drivesdk', 'https://swfilesystem.ledlenser.com/prod/public/media/68/34/89/1750928744/Warnings_25Languages_V5-50x38cm-20240507.pdf?ts=1768789724', 'headlamp,rechargeable head lamp,RGB headlamp,autofocus head torch,digital head lamp,helmet headlamp,professional headtorch,work headlamp,work head torch,Bluetooth headlamp,head torch with app control,high-end headlamp', 'Ledlenser Product Data Import File V1.0 11-2.xlsx'),
  ('503316', 'Ledlenser HF4 Black Headlamp', '847706104133', '847706104133', 'Headlamps > HF Series', 'Headlamps', 'HF Series', 'Complete', 'HF4', 'Standard', 'Black', 'Compact and simple, yet effective: With the HF4 headlamp, you are ready for any task around the house and garden.', 'Gardening or working around the house: With the compact HF4, even everyday tasks can turn into small adventures—grab your headlamp and reveal what lies in the dark. Illuminate narrow basement staircases or dark corners of your garden shed with spot for long-range and flood light for close-up illumination. To help you preserve your night vision, you can also use the additional red front light. The HF4 operates with both disposable and rechargeable batteries—so you never run out of light. To match your headlamp to your style, you can choose from three different colorways. And: Our lights are made for a brighter future—therefore, your HF4 contains recycled materials13.', 'Compact headlamp with spot for long-range and flood light for close-up illumination | Additional red front light to preserve night vision | Dual Power Source: Operates with rechargeable and disposable batteries (3x AAA alkaline batteries included) | Sustainable: Use of recycled materials13 and 7-year warranty* | Element-proof: High water and dust resistance (IP67)', 39.95, 450, 20, 'IP67', 102, false, 'Polymer Li-Ion Battery Pack 1350mAh (3.85V, 5.2Wh) / 3x AAA Alkaline', 'Connect Adapter - HF 2026, 1 set of batteries (3x AAA alkaline)', 'https://www.youtube.com/watch?v=YYX4LkWK8DM', 'https://drive.google.com/file/d/1ZhUTYR-KIA5YtWBBdvjm_ClEtK9szq2M/view?usp=drivesdk', 'https://swfilesystem.ledlenser.com/prod/public/media/68/34/89/1750928744/Warnings_25Languages_V5-50x38cm-20240507.pdf?ts=1768789724', 'headlamp,head lamp,head torch,compact headlamp,allround head torch,headlamp with red light', 'Ledlenser Product Data Import File V1.0 11-2.xlsx'),
